#!/usr/bin/env python3
import sys
import re
from Bio import SeqIO
from Bio.Seq import translate

def extract_gene_tag(header):
    """Extract gene tag from FASTA header like [gene=TP53]"""
    match = re.search(r'\[gene=(\w+)\]', header)
    if match:
        return match.group(1)
    return None

def main():
    if len(sys.argv) != 2:
        sys.exit(0)

    fasta_file = sys.argv[1]

    for record in SeqIO.parse(fasta_file, "fasta"):
        gene = extract_gene_tag(record.description)
        if gene is None:
            continue

        # Translate from first base with standard genetic code, stop at first stop codon
        protein = translate(record.seq, to_stop=True, cds=True, stop_symbol='*')

        # Length excludes stop codon (handled by to_stop=True)
        length = len(protein)

        print(f"{gene}\t{length}")

if __name__ == "__main__":
    main()
