import sys
from Bio import SeqIO

def reverse_complement(seq):
    complement = {'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G', 'N': 'N'}
    return ''.join(complement.get(base, 'N') for base in reversed(seq))

def find_orfs(seq):
    orfs = []
    for i in range(len(seq) - 2):
        if seq[i:i+3] == 'ATG':
            for j in range(i, len(seq) - 2, 3):
                codon = seq[j:j+3]
                if codon in ['TAA', 'TAG', 'TGA']:
                    orf_length = j - i + 3
                    orfs.append((i, j, orf_length))
                    break
    return orfs

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    fasta_file = sys.argv[1]

    record = SeqIO.read(fasta_file, 'fasta')
    seq = str(record.seq).upper()

    forward_orfs = find_orfs(seq)
    rev_comp = reverse_complement(seq)
    reverse_orfs = find_orfs(rev_comp)

    all_orfs = forward_orfs + reverse_orfs
    if not all_orfs:
        sys.exit(0)

    all_orfs.sort(key=lambda x: x[2], reverse=True)
    longest = all_orfs[0]
    start, end, length = longest

    if longest in forward_orfs:
        strand = '+'
        start_1based = start + 1
        end_1based = end + 1
    else:
        strand = '-'
        seq_len = len(seq)
        start_1based = seq_len - end
        end_1based = seq_len - start

    print(f"{start_1based} {end_1based} {strand} {length}")

if __name__ == "__main__":
    main()
