import sys
from collections import Counter

def main():
    if len(sys.argv) < 2:
        return

    filename = sys.argv[1]
    counts = Counter()
    total_cds_bp = 0

    with open(filename, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue

            parts = line.split('\t')
            if len(parts) < 5:
                continue

            feature_type = parts[2]
            counts[feature_type] += 1

            if feature_type == 'CDS':
                try:
                    start = int(parts[3])
                    end = int(parts[4])
                    length = end - start + 1
                    total_cds_bp += length
                except ValueError:
                    pass

    for feature_type in sorted(counts.keys()):
        print(f"{feature_type}\t{counts[feature_type]}")

    print(f"total_cds_bp\t{total_cds_bp}")

if __name__ == "__main__":
