import sys
import pandas as pd

def parse_vcf(vcf_file):
    records = []
    with open(vcf_file, 'r') as f:
        for line in f:
            if line.startswith('#'):
                continue
            parts = line.strip().split('\t')
            if len(parts) < 8:
                continue
            chrom = parts[0]
            pos = parts[1]
            ref = parts[3]
            alt = parts[4]
            qual_str = parts[6] if len(parts) > 6 else '.'
            qual = float(qual_str) if qual_str != '.' else 0.0
            filter_val = parts[7] if len(parts) > 7 else '.'
            info = parts[8] if len(parts) > 8 else ''

            if filter_val != 'PASS':
                continue
            if qual < 30:
                continue

            dp = None
            for item in info.split(';'):
                if item.startswith('DP='):
                    try:
                        dp = int(item.split('=')[1])
                        break
                    except (ValueError, IndexError):
                        continue
            if dp is None or dp < 10:
                continue

            records.append({
                'ref': ref,
                'alt': alt,
                'qual': qual,
                'filter': filter_val,
                'info': info
            })
    return records

def classify_variant(ref, alt):
    if len(ref) == 1 and len(alt) == 1:
        return 'SNV'
    return 'indel'

def is_transition(ref, alt):
    ref, alt = ref.upper(), alt.upper()
    return (ref in 'AG' and alt in 'AG') or (ref in 'CT' and alt in 'CT')

def compute_titv_ratio(snv_list):
    if not snv_list:
        return 0.0
    trans = 0
    transversion = 0
    for ref, alt in snv_list:
        if ref.upper() == alt.upper():
            continue
        if is_transition(ref, alt):
            trans += 1
        else:
            transversion += 1
    if transversion == 0:
        return float(trans)
    return trans / transversion

def main():
    vcf_file = sys.argv[1]
    records = parse_vcf(vcf_file)

    kept = len(records)
    snv_list = []
    indel_count = 0
    snv_count = 0

    for rec in records:
        variant_type = classify_variant(rec['ref'], rec['alt'])
        if variant_type == 'SNV':
            snv_list.append((rec['ref'], rec['alt']))
            snv_count += 1
        else:
            indel_count += 1

    titv = compute_titv_ratio(snv_list)
    print(f"kept={kept} snv={snv_count} indel={indel_count} titv={titv:.3f}")

if __name__ == '__main__':
    main()
