import sys

def main():
    if len(sys.argv) < 2:
        return

    filename = sys.argv[1]
    total_reads = 0
    pass_q20 = 0
    sum_means = 0.0

    try:
        with open(filename, 'r') as f:
            buffer = []
            for line in f:
                # Strip newline characters, keep internal content
                buffer.append(line.rstrip('\n\r'))
                if len(buffer) == 4:
                    # Process the record
                    qual = buffer[3]
                    if qual:
                        scores = [ord(c) - 33 for c in qual]
                        mean = sum(scores) / len(scores)
                        total_reads += 1
                        sum_means += mean
                        if mean >= 20:
                            pass_q20 += 1
                    buffer = []
    except FileNotFoundError:
        pass
    except Exception:
        pass

    if total_reads == 0:
        print("reads=0 pass_q20=0 mean_q=0.00")
    else:
        print(f"reads={total_reads} pass_q20={pass_q20} mean_q={sum_means / total_reads:.2f}")

if __name__ == "__main__":
    main()
